"OLAYLAR_ORTACAG_IBERYA_MAGRIB:0976-10-02:0":{"b": ["Baada ya kifo cha II. Hakam, II. Hisham mwenye umri wa miaka kumi na moja-kumi na miwili alikuwa khalifa.", "359fba92"], "d": ["Baada ya kifo cha II. Hakam, II. Hisham mwenye umri wa miaka kumi na moja-kumi na miwili alikuwa khalifa.", "359fba92"]},
