"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:0903-07-01:0":{"b": ["Wakarmatî wazingira Dımaşk; kiongozi Sâhibünnâka Yahyâ auawa wakati wa kuzingirwa", "9b876cc8"], "d": ["Yahyâ, mmoja wa wana wa Zikreveyh b. Mihreveyh anayejulikana kwa jina Sâhibünnâka, aliuawa wakati wa kuzingirwa kwa Dımaşk mwezi wa Şâban 290 (Julai 903); kaka yake Sâhibüşşâme alichukua nafasi yake, na baada ya shambulio lisilofanikiwa dhidi ya Aleppo aliteka Hama, Humus, Maarretünnu‘mân na Ba‘lebek.", "9980a87c"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:0906-01-01:0":{"b": ["Mwalimu wa Kikarmatî Ebû Gānim aingia Kûfe baada ya kupora Busrâ, Tiberias na Hît; aondolewa muda mfupi", "7b175ddd"], "d": ["Ebû Gānim Abdullah b. Saîd na watu wake, waliotumwa na Zikreveyh kufufua Ukarmatî kati ya Benî Kelb, waliporaa makazi kama Busrâ, Ezriât, Tiberias na Hît na kushambulia Dımaşk; kwa kutopata mafanikio waliingia Kûfe lakini waliondolewa mjini muda mfupi (293/906).", "e62c81d1"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:0911-01-01:0":{"b": ["Dola ya Uygur ya Turfan yawa huru", "d48689ad"], "d": ["Dola ya Uygur ya Turfan yawa huru", "d48689ad"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:0913-01-01:0":{"b": ["Ebû Saîd el-Cennâbî auawa kwa shambulio la kuvizia lililopangwa na Ubeydullah el-Mehdî (301); wanawe waendeleza dola.", "dd507fc0"], "d": ["Ebû Saîd el-Cennâbî auawa kwa shambulio la kuvizia lililopangwa na Ubeydullah el-Mehdî (301); wanawe waendeleza dola.", "dd507fc0"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:0931-01-24:0":{"b": ["Ebû Tâhir amkabidhi Mwajemi aliyemtambulisha kama mehdî utawala wa Bahrain; mehdî mpya auawa baada ya siku themanini", "1816f4a5"], "d": ["Ebû Tâhir el-Cennâbî, aliyeteka Oman (318/930), mwaka uliofuata alikabidhi utawala wa Bahrain kwa Mwajemi aliyemleta kutoka İsfahan na kumtambulisha kwa watu kama mehdî. Mwajemi huyo, aliyejitambulisha kama mzao wa makisra wa zamani wa Uajemi na mrekebishaji wa dini ya Kiajemi, alipotoa mawazo dhidi ya Waarabu, siku themanini baada ya kuteuliwa aliuawa na Ebû Tâhir; hili lilisababisha mshangao mkubwa na kutawanyika miongoni mwa Wakarmatî wa Bahrain.", "919b72ac"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:0935-01-01:0":{"b": ["Merdâvîc auawa na askari wa Kituruki huko İsfahan; kaka yake Veşmgîr achukua nafasi yake (323/935).", "11355262"], "d": ["Merdâvîc auawa na askari wa Kituruki huko İsfahan; kaka yake Veşmgîr achukua nafasi yake (323/935).", "11355262"]},
