"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:1127-01-17:0":{"b": ["Sultani Sencer azingira Alamut; ngome haikuchukuliwa", "6b06eb0c"], "d": ["Sultani wa Seljuk Sencer mwaka 521 (1127) alizingira Alamut, kituo cha Waismaili wa Nizârî; kuteka ngome hakukuwezekana.", "91215716"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:1130-01-01:0":{"b": ["Sultani Mahmûd b. Muhammed Tapar azingira Alamut; ngome haikuchukuliwa", "64d6b833"], "d": ["Sultani wa Seljuk Mahmûd b. Muhammed Tapar mwaka 524 (1130) alizingira Alamut; ngome haikuanguka.", "791399dc"]},
